edits.newText:
// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Issue #1: the ball bounces off bricks (per-face, once, no tunnelling) --

// Minimal state around a ball and a brick grid. `px`/`py` default to the ball
// position so the sweep is inert unless a test deliberately moves the ball.
function makeBrickState(bricks, ball) {
  const b = { r: 7, px: ball.x, py: ball.y, ...ball };
  return { level: 1, combo: 0, score: 0, bricks, ball: b };
}

function brickAt(x, y) {
  return { x, y, w: 72, h: 20, alive: true, points: 10 };
}

test('bounceBricks: top-face hit flips vy and pushes the ball up', () => {
  const state = makeBrickState([brickAt(100, 100)], { x: 136, y: 105, vx: 50, vy: 300 });
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vy, -300); // flipped up
  assert.equal(state.ball.vx, 50); // untouched
  assert.equal(state.ball.y, 93); // pushed out above the brick
  assert.equal(state.bricks[0].alive, false);
  assert.equal(state.combo, 1);
});

test('bounceBricks: bottom-face hit flips vy and pushes the ball down', () => {
  const state = makeBrickState([brickAt(100, 100)], { x: 136, y: 115, vx: -50, vy: -300 });
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vy, 300);
  assert.equal(state.ball.vx, -50);
  assert.equal(state.ball.y, 127); // brick bottom (120) + r
});

test('bounceBricks: left-face hit flips vx and pushes the ball out sideways', () => {
  const state = makeBrickState([brickAt(100, 100)], { x: 105, y: 110, vx: 300, vy: -40 });
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vx, -300);
  assert.equal(state.ball.vy, -40); // untouched
  assert.equal(state.ball.x, 93);
});

test('bounceBricks: right-face hit flips vx and pushes the ball out sideways', () => {
  const state = makeBrickState([brickAt(100, 100)], { x: 165, y: 110, vx: -300, vy: 40 });
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vx, 300);
  assert.equal(state.ball.vy, 40); // untouched
  assert.equal(state.ball.x, 179); // brick right edge (172) + r
});

test('bounceBricks: corner hit (equal penetrations) flips both components', () => {
  const state = makeBrickState([brickAt(100, 100)], { x: 98, y: 98, vx: 300, vy: 300 });
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vx, -300);
  assert.equal(state.ball.vy, -300);
  assert.equal(state.ball.x, 93);
  assert.equal(state.ball.y, 93);
});

test('bounceBricks: push-out leaves the ball clear of the brick (no sticky bounce)', () => {
  for (const setup of [
    { x: 136, y: 105, vx: 0, vy: 300 }, // top
    { x: 105, y: 110, vx: 300, vy: 0 }, // left
    { x: 165, y: 110, vx: -300, vy: 0 }, // right
    { x: 136, y: 115, vx: 0, vy: -300 }, // bottom
  ]) {
    const state = makeBrickState([brickAt(100, 100)], setup);
    bounceBricks(state);
    assert.equal(
      collides(state.ball, state.bricks[0]),
      false,
      `ball must be clear of the brick (${JSON.stringify(setup)})`,
    );
  }
});

test('bounceBricks: seam between two side-by-side bricks bounces exactly once', () => {
  const state = makeBrickState(
    [brickAt(100, 100), brickAt(180, 100)],
    { x: 176, y: 105, vx: 0, vy: 300 },
  );
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vy, -300); // flipped exactly once, NOT back to +300
  assert.equal(state.ball.vx, 0);
  assert.equal(state.ball.y, 93);
  assert.ok(state.bricks.every((b) => !b.alive));
});

test('bounceBricks: row gap (stacked bricks) is a single obstacle', () => {
  const state = makeBrickState(
    [brickAt(100, 100), brickAt(100, 128)],
    { x: 94, y: 124, vx: 300, vy: 0 },
  );
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vx, -300); // flipped exactly once
  assert.equal(state.ball.x, 93); // pushed out to the left of the cluster
  assert.ok(state.bricks.every((b) => !b.alive));
});

test('bounceBricks: high-speed ball cannot tunnel through a brick', () => {
  // The ball jumps from y = 92 to y = 130 in one step (38 px > 34 px needed
  // to cross brick + diameter): no overlap at either endpoint, only the sweep
  // between the two positions catches it.
  const state = makeBrickState(
    [brickAt(100, 100)],
    { x: 136, y: 130, vx: 0, vy: 300, px: 136, py: 92 },
  );
  assert.equal(bounceBricks(state), true);
  assert.equal(state.ball.vy, -300);
  assert.equal(state.ball.y, 93); // placed back at the face it crossed
  assert.equal(state.bricks[0].alive, false);
});

test('bounceBricks: no hit, nothing changes', () => {
  const state = makeBrickState([brickAt(100, 100)], { x: 320, y: 300, vx: 0, vy: 300 });
  assert.equal(bounceBricks(state), false);
  assert.equal(state.bricks[0].alive, true);
  assert.equal(state.combo, 0);
  assert.equal(state.score, 0);
});

