// --- Brick collision (issue #1): pure, testable resolution -----------------

// Bounding box covering a set of bricks. The ball is bigger than the grid
// seams (14 px across vs 8 px gaps), so every seam overlaps two bricks in the
// same pass: resolving against their union turns the cluster into ONE obstacle
// and guarantees the bounce is applied exactly once (`vy = -vy` twice cancels
// out and the ball would go straight through — the old bug).
function unionBox(bricks) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const b of bricks) {
    if (b.x < minX) minX = b.x;
    if (b.y < minY) minY = b.y;
    const bx = b.x + b.w;
    const by = b.y + b.h;
    if (bx > maxX) maxX = bx;
    if (by > maxY) maxY = by;
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

// Entry of the segment (x0,y0)→(x1,y1) into the box expanded by `r` (slab
// method). Returns { x, y, axis } — the entry point and the face axis it
// crossed ('x' = vertical face, 'y' = horizontal face) — or null when the
// segment never enters. `axis` is the slab whose entry parameter is the
// largest: that is the face the ball actually strikes first.
function segmentEntry(x0, y0, x1, y1, box, r) {
  const ex0 = box.x - r;
  const ex1 = box.x + box.w + r;
  const ey0 = box.y - r;
  const ey1 = box.y + box.h + r;
  const dx = x1 - x0;
  const dy = y1 - y0;
  let t0 = 0;
  let t1 = 1;
  let axis = null;

  if (dx === 0) {
    if (x0 <= ex0 || x0 >= ex1) return null; // parallel to the slab, outside
  } else {
    let ta = (ex0 - x0) / dx;
    let tb = (ex1 - x0) / dx;
    if (ta > tb) {
      const t = ta;
      ta = tb;
      tb = t;
    }
    if (ta > t0) {
      t0 = ta;
      axis = 'x';
    }
    if (tb < t1) t1 = tb;
    if (t0 > t1) return null;
  }

  if (dy === 0) {
    if (y0 <= ey0 || y0 >= ey1) return null; // parallel to the slab, outside
  } else {
    let ta = (ey0 - y0) / dy;
    let tb = (ey1 - y0) / dy;
    if (ta > tb) {
      const t = ta;
      ta = tb;
      tb = t;
    }
    if (ta > t0) {
      t0 = ta;
      axis = 'y';
    }
    if (tb < t1) t1 = tb;
    if (t0 > t1) return null;
  }

  if (t0 < 0 || t0 > 1) return null; // entry before/after the travelled segment
  return { x: x0 + dx * t0, y: y0 + dy * t0, axis };
}

// True if the segment swept between the ball's previous and current position
// enters the brick's rectangle expanded by the ball radius — i.e. the ball
// crossed this brick this step even though it may not overlap it at either
// endpoint (high-speed tunnelling: at level 6 a capped 50 ms frame moves the
// ball ~35.5 px against the 34 px needed to cross a brick + diameter).
function sweptThrough(brick, x0, y0, x1, y1, r) {
  return segmentEntry(x0, y0, x1, y1, brick, r) !== null;
}

// Bounces the ball out of a box it overlaps, using the smallest-penetration
// rule: the axis with the smaller penetration is the face that was hit — flip
// that component and leave the other exactly as it was; equal penetrations
// mean a diagonal hit, flip both. Always pushes the ball back outside the box
// so it cannot re-overlap on the next frame (sticky bounce).
function resolveOverlap(ball, box) {
  const left = ball.x + ball.r - box.x;
  const right = box.x + box.w - (ball.x - ball.r);
  const top = ball.y + ball.r - box.y;
  const bottom = box.y + box.h - (ball.y - ball.r);
  const dx = Math.min(left, right);
  const dy = Math.min(top, bottom);

  if (Math.abs(dx - dy) < 1e-9) {
    // Corner: diagonal hit — flip both components, exit through the corner.
    ball.vx = left <= right ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.vy = top <= bottom ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.x = left <= right ? box.x - ball.r : box.x + box.w + ball.r;
    ball.y = top <= bottom ? box.y - ball.r : box.y + box.h + ball.r;
  } else if (dx < dy) {
    // Side hit: flip vx, push out horizontally.
    ball.vx = left <= right ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.x = left <= right ? box.x - ball.r : box.x + box.w + ball.r;
  } else {
    // Top/bottom hit: flip vy, push out vertically.
    ball.vy = top <= bottom ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.y = top <= bottom ? box.y - ball.r : box.y + box.h + ball.r;
  }
}

// Keeps the push-out inside the field (a side hit on the leftmost column
// would otherwise park the ball a few pixels off-screen until step() clamps).
function clampToField(ball) {
  if (ball.x < ball.r) ball.x = ball.r;
  else if (ball.x > WIDTH - ball.r) ball.x = WIDTH - ball.r;
  if (ball.y < ball.r) ball.y = ball.r;
  else if (ball.y > HEIGHT - ball.r) ball.y = HEIGHT - ball.r;
}

// Resolves the ball against the brick grid for one time step (issue #1).
//
// All hits — discrete overlap AND swept tunnel — are gathered in a single
// pass, so a seam overlapping two bricks in the same pass is treated as one
// obstacle and the bounce applies exactly once. Hit bricks die (combo/score
// included), then the ball is deflected per face (smallest penetration), or
// both components on a diagonal corner hit, and pushed back out.
//
// `step()` records the pre-move position in `ball.px`/`ball.py`; when those
// are absent (hand-built states) the sweep is inert.
//
// Returns true if at least one brick was hit.
export function bounceBricks(state) {
  const { ball, bricks } = state;
  const prevX = ball.px ?? ball.x;
  const prevY = ball.py ?? ball.y;

  const hit = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick) || sweptThrough(brick, prevX, prevY, ball.x, ball.y, ball.r)) {
      hit.push(brick);
    }
  }
  if (hit.length === 0) return false;

  for (const brick of hit) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  const box = unionBox(hit);
  if (collides(ball, box)) {
    resolveOverlap(ball, box);
  } else {
    // Tunneled: put the ball back at the face it crossed and bounce off it.
    const entry = segmentEntry(prevX, prevY, ball.x, ball.y, box, ball.r);
    if (entry) {
      ball.x = entry.x;
      ball.y = entry.y;
      if (entry.axis === 'x') ball.vx = -ball.vx;
      else ball.vy = -ball.vy;
    }
  }
  clampToField(ball);
  return true;
}

// --- Rendering (DOM): brick collision triggered from here -------------------

// Main render loop. Collision resolution is delegated to the pure
// `bounceBricks()` (see #1); only the drawing of the surviving bricks remains
// in this pass.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: bounce + score handled by bounceBricks(), drawing here.
  bounceBricks(state);
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

